class Solution {
public:
    ListNode* removeZeroSumSublists(ListNode* head) {
        ListNode* dummy = new ListNode(0);
        dummy->next = head;
        unordered_map<int, ListNode*> mp;
        int sum = 0;
        for (ListNode* p = dummy; p; p = p->next) {
            sum += p->val;
            mp[sum] = p;
        }
        sum = 0;
        for (ListNode* p = dummy; p; p = p->next) {
            sum += p->val;
            p->next = mp[sum]->next;
        }
        return dummy->next;
    }
};
